-- Generated by `bun run db:snapshot` from the drizzle migrations. Do not edit.
-- First-time setup only: services still apply incremental migrations at startup.
-- Contains the full schema, seed data and the __drizzle_migrations rows
-- (so the migrator treats every existing migration as applied).
BEGIN;
PRAGMA defer_foreign_keys = ON;
CREATE TABLE "__drizzle_migrations" (
				id SERIAL PRIMARY KEY,
				hash text NOT NULL,
				created_at numeric
			);
CREATE TABLE `blocked_ips` (
	`id` text PRIMARY KEY NOT NULL,
	`ip_hash` text NOT NULL,
	`channel_id` text,
	`reason` text NOT NULL,
	`created_at` integer NOT NULL,
	`expires_at` integer NOT NULL, `ip` text,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE INDEX `blocked_ips_hash_idx` ON `blocked_ips` (`ip_hash`);
CREATE TABLE `channels` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`kind` text NOT NULL,
	`name` text NOT NULL,
	`access_mode` text NOT NULL,
	`publishable_key` text,
	`secret_key_hash` text,
	`allowed_origins` text DEFAULT '[]' NOT NULL,
	`disabled_at` integer,
	`created_at` integer NOT NULL
, `catalog_language` text DEFAULT 'en' NOT NULL);
CREATE UNIQUE INDEX `channels_slug_unique` ON `channels` (`slug`);
CREATE UNIQUE INDEX `channels_publishable_key_unique` ON `channels` (`publishable_key`);
CREATE TABLE `llm_calls` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`at` integer NOT NULL,
	`user_id` text,
	`channel_id` text,
	`thread_id` text,
	`plan_run_id` text,
	`action_name` text,
	`kind` text NOT NULL,
	`provider` text NOT NULL,
	`model` text NOT NULL,
	`input_tokens` integer,
	`output_tokens` integer,
	`latency_ms` integer NOT NULL,
	`ok` integer NOT NULL,
	`error` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`thread_id`) REFERENCES `threads`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`plan_run_id`) REFERENCES `plan_runs`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE INDEX `llm_calls_user_at_idx` ON `llm_calls` (`user_id`,`at`);
CREATE INDEX `llm_calls_channel_at_idx` ON `llm_calls` (`channel_id`,`at`);
CREATE INDEX `llm_calls_run_idx` ON `llm_calls` (`plan_run_id`);
CREATE INDEX `llm_calls_at_idx` ON `llm_calls` (`at`);
CREATE TABLE `messages` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`thread_id` text NOT NULL,
	`user_id` text NOT NULL,
	`role` text NOT NULL,
	`content` text NOT NULL,
	`created_at` integer NOT NULL,
	`plan_run_id` text,
	FOREIGN KEY (`thread_id`) REFERENCES `threads`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`plan_run_id`) REFERENCES `plan_runs`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE INDEX `messages_user_idx` ON `messages` (`user_id`,`id`);
CREATE INDEX `messages_thread_idx` ON `messages` (`thread_id`,`id`);
CREATE TABLE `plan_events` (
	`run_id` text NOT NULL,
	`seq` integer NOT NULL,
	`type` text NOT NULL,
	`attempt` integer NOT NULL,
	`action` text,
	`payload` text NOT NULL,
	`at` integer NOT NULL,
	PRIMARY KEY(`run_id`, `seq`),
	FOREIGN KEY (`run_id`) REFERENCES `plan_runs`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `plan_runs` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`thread_id` text NOT NULL,
	`goal` text NOT NULL,
	`succeeded` integer NOT NULL,
	`attempts` integer NOT NULL,
	`duration_ms` integer NOT NULL,
	`created_at` integer NOT NULL, `root_run_id` text, `prompt` text, `steps` text,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`thread_id`) REFERENCES `threads`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE INDEX `plan_runs_user_idx` ON `plan_runs` (`user_id`,`created_at`);
CREATE TABLE `threads` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`channel_id` text NOT NULL,
	`external_thread_id` text,
	`created_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE UNIQUE INDEX `threads_channel_user_external_uq` ON `threads` (`channel_id`,`user_id`,`external_thread_id`);
CREATE INDEX `threads_external_idx` ON `threads` (`external_thread_id`);
CREATE TABLE `users` (
	`id` text PRIMARY KEY NOT NULL,
	`channel_id` text NOT NULL,
	`external_user_id` text,
	`kind` text NOT NULL,
	`display_name` text,
	`created_at` integer NOT NULL,
	`last_seen_at` integer NOT NULL,
	`whitelisted_at` integer,
	`whitelisted_by` text,
	`blocked_at` integer,
	`blocked_reason` text,
	`blocked_by` text, `last_ip` text,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE UNIQUE INDEX `users_channel_external_uq` ON `users` (`channel_id`,`external_user_id`);
CREATE INDEX `users_last_seen_idx` ON `users` (`last_seen_at`);
CREATE INDEX `users_kind_last_seen_idx` ON `users` (`kind`,`last_seen_at`);
CREATE TABLE `visitor_tokens` (
	`token_hash` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`channel_id` text NOT NULL,
	`created_at` integer NOT NULL,
	`last_used_at` integer NOT NULL,
	`expires_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `thread_world_state` (
	`thread_id` text PRIMARY KEY NOT NULL,
	`state` text NOT NULL,
	`updated_at` integer NOT NULL, `goal` text NOT NULL,
	FOREIGN KEY (`thread_id`) REFERENCES `threads`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE INDEX `plan_runs_root_idx` ON `plan_runs` (`root_run_id`);
CREATE TABLE `mcp_catalogs` (
	`channel_id` text NOT NULL,
	`hash` text NOT NULL,
	`tools` text NOT NULL,
	`tool_count` integer NOT NULL,
	`first_seen_at` integer NOT NULL,
	`last_seen_at` integer NOT NULL,
	`registrations` integer NOT NULL,
	PRIMARY KEY(`channel_id`, `hash`),
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE INDEX `mcp_catalogs_seen_idx` ON `mcp_catalogs` (`channel_id`,`last_seen_at`);
CREATE TABLE `intent_examples` (
	`id` text PRIMARY KEY NOT NULL,
	`channel_id` text NOT NULL,
	`text_key` text NOT NULL,
	`sample` text NOT NULL,
	`intent` text NOT NULL,
	`source` text NOT NULL,
	`status` text NOT NULL,
	`plan_run_id` text,
	`seen_count` integer DEFAULT 1 NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`plan_run_id`) REFERENCES `plan_runs`(`id`) ON UPDATE no action ON DELETE set null
);
CREATE UNIQUE INDEX `intent_examples_key_idx` ON `intent_examples` (`channel_id`,`text_key`);
CREATE INDEX `intent_examples_status_idx` ON `intent_examples` (`status`,`updated_at`);
CREATE TABLE `channel_persona` (
	`channel_id` text PRIMARY KEY NOT NULL,
	`bot_name` text DEFAULT '' NOT NULL,
	`tone` text DEFAULT '' NOT NULL,
	`default_lang` text DEFAULT '' NOT NULL,
	`greeting` text DEFAULT '' NOT NULL,
	`forbidden_topics` text DEFAULT '[]' NOT NULL,
	`handoff_contact` text DEFAULT '' NOT NULL,
	`updated_at` integer NOT NULL, `instructions` text DEFAULT '' NOT NULL,
	FOREIGN KEY (`channel_id`) REFERENCES `channels`(`id`) ON UPDATE no action ON DELETE cascade
);
